var e={"l0-o-que-e-computador":[{id:`l0-o-que-e-computador#1`,front:`Quais são as quatro funções básicas de um sistema computacional?`,back:`Entrada (input), processamento (processing), armazenamento (storage) e saída (output).`},{id:`l0-o-que-e-computador#2`,front:`Diferença entre hardware e software?`,back:`Hardware é a parte física; software são as instruções (programas) que o hardware executa.`},{id:`l0-o-que-e-computador#3`,front:`Por que um computador é chamado de máquina universal?`,back:`Porque o programa é um dado na memória: trocando o programa, a mesma máquina faz tarefas diferentes.`}],"l0-bits-bytes":[{id:`l0-bits-bytes#1`,front:`Quanto vale o binário 1011?`,back:`8 + 0 + 2 + 1 = 11.`},{id:`l0-bits-bytes#2`,front:`Quantos valores cabem em 1 byte?`,back:`256 (de 0 a 255), pois 2⁸ = 256.`},{id:`l0-bits-bytes#3`,front:`O que é UTF-8?`,back:`Uma codificação (encoding) que transforma códigos Unicode em sequências de 1 a 4 bytes.`}],"l0-cpu-memoria":[{id:`l0-cpu-memoria#1`,front:`Quais são as etapas do ciclo de instrução?`,back:`Buscar (fetch), decodificar (decode) e executar (execute).`},{id:`l0-cpu-memoria#2`,front:`Por que a RAM é chamada de volátil?`,back:`Porque perde o conteúdo quando fica sem energia.`},{id:`l0-cpu-memoria#3`,front:`O que é cache?`,back:`Uma memória menor e mais rápida que guarda cópias de dados usados com frequência para evitar acessos lentos.`}],"l0-software-so":[{id:`l0-software-so#1`,front:`Cite quatro responsabilidades do sistema operacional.`,back:`Gerenciar processos, memória, arquivos e dispositivos.`},{id:`l0-software-so#2`,front:`O que é uma system call?`,back:`Um pedido de um programa ao kernel por um serviço privilegiado (abrir arquivo, usar a rede...).`},{id:`l0-software-so#3`,front:`Programa × processo?`,back:`Programa é o arquivo com instruções; processo é uma execução dele, com memória e estado.`}],"l0-arquivos-terminal":[{id:`l0-arquivos-terminal#1`,front:"O que significa `..` em um caminho?",back:`A pasta mãe (um nível acima).`},{id:`l0-arquivos-terminal#2`,front:"O que faz `pwd`?",back:`Mostra o diretório de trabalho atual (print working directory).`},{id:`l0-arquivos-terminal#3`,front:`Diferença entre caminho absoluto e relativo?`,back:`Absoluto começa na raiz (/); relativo começa no diretório atual.`}],"l0-internet":[{id:`l0-internet#1`,front:`O que o DNS faz?`,back:`Traduz nomes de domínio (exemplo.com) em endereços IP.`},{id:`l0-internet#2`,front:`O que significam as faixas 4xx e 5xx?`,back:`4xx: erro do cliente (pedido inválido, não encontrado, sem permissão). 5xx: erro do servidor.`},{id:`l0-internet#3`,front:`Qual porta o HTTPS usa por padrão?`,back:`443 (HTTP usa 80).`}],"l0-ingles-tecnico":[{id:`l0-ingles-tecnico#1`,front:`O que significa "actual value" em um teste?`,back:`O valor obtido de fato (não "atual").`},{id:`l0-ingles-tecnico#2`,front:`O que é "deprecated"?`,back:`Obsoleto: ainda funciona, mas será removido; prefira a alternativa.`},{id:`l0-ingles-tecnico#3`,front:`Por onde começar a ler um traceback do Python?`,back:`Pela última linha: tipo do erro e mensagem. Depois as linhas acima, que mostram onde ocorreu.`}],"l1-algoritmos":[{id:`l1-algoritmos#1`,front:`Quais propriedades um algoritmo deve ter?`,back:`Ser finito, preciso (não ambíguo), efetivo e ter entrada e saída definidas.`},{id:`l1-algoritmos#2`,front:`O que é decomposição?`,back:`Dividir um problema grande em subproblemas menores e mais fáceis.`},{id:`l1-algoritmos#3`,front:`Quais são as quatro fases de Pólya?`,back:`Entender o problema, criar um plano, executar o plano, revisar.`}],"l1-variaveis":[{id:`l1-variaveis#1`,front:"O que acontece em `x = x + 1`?",back:`Calcula-se o valor atual de x mais 1, e x passa a apontar para o novo valor.`},{id:`l1-variaveis#2`,front:"Depois de `y = x` e `x = 10`, y muda?",back:`Não (para números): y continua com o valor antigo de x.`},{id:`l1-variaveis#3`,front:`Como trocar a e b em Python numa linha?`,back:"`a, b = b, a`"}],"l1-tipos-operadores":[{id:`l1-tipos-operadores#1`,front:`Quanto é 7 // 2 e 7 % 2?`,back:`3 e 1.`},{id:`l1-tipos-operadores#2`,front:`Diferença entre = e ==?`,back:`= atribui um valor; == compara dois valores e devolve True/False.`},{id:`l1-tipos-operadores#3`,front:`Por que 0.1 + 0.2 != 0.3?`,back:`Porque floats são representações binárias aproximadas (IEEE 754).`},{id:`l1-tipos-operadores#4`,front:`Qual a ordem de precedência entre and e or?`,back:`and é avaliado antes de or.`}],"l1-entrada-saida":[{id:`l1-entrada-saida#1`,front:`Qual o tipo devolvido por input()?`,back:`Sempre str.`},{id:`l1-entrada-saida#2`,front:`Como mostrar um float com 2 casas decimais numa f-string?`,back:`f"{valor:.2f}"`}],"l1-condicionais":[{id:`l1-condicionais#1`,front:`Se duas condições de um if/elif forem verdadeiras, quantos blocos executam?`,back:`Apenas o primeiro verdadeiro.`},{id:`l1-condicionais#2`,front:`O que é um edge case?`,back:`Um caso nos limites da entrada (0, vazio, valor máximo, igualdade) onde bugs costumam aparecer.`},{id:`l1-condicionais#3`,front:"Quando `A or B` é falso?",back:`Somente quando A e B são falsos.`}],"l1-loops":[{id:`l1-loops#1`,front:`Quais números range(1, 5) gera?`,back:`1, 2, 3, 4.`},{id:`l1-loops#2`,front:`O que causa um loop infinito com while?`,back:`Nada dentro do loop muda a condição para falsa.`},{id:`l1-loops#3`,front:`O que é um off-by-one error?`,back:`Um erro em que o loop executa uma vez a mais ou a menos (geralmente por causa dos limites).`}],"l1-funcoes":[{id:`l1-funcoes#1`,front:`Diferença entre parâmetro e argumento?`,back:`Parâmetro é o nome na definição; argumento é o valor passado na chamada.`},{id:`l1-funcoes#2`,front:`O que uma função sem return devolve?`,back:`None.`},{id:`l1-funcoes#3`,front:`Por que preferir return a print em funções?`,back:`Porque return entrega o valor ao código, permitindo reutilizar, testar e combinar o resultado.`}],"l1-decomposicao":[{id:`l1-decomposicao#1`,front:`Quais são os 5 passos da receita de projeto?`,back:`Assinatura, propósito, exemplos, implementação e testes.`},{id:`l1-decomposicao#2`,front:`Por que escrever exemplos antes do código?`,back:`Para garantir que entendeu o problema e já ter os testes prontos.`}],"l2-por-que-python":[{id:`l2-por-que-python#1`,front:`Por que Python é a primeira linguagem desta trilha?`,back:`Sintaxe com pouco ruído, mensagens de erro claras, execução no navegador e uso em cursos de referência; outras linguagens entram depois para cobrir o que Python esconde.`},{id:`l2-por-que-python#2`,front:`O que é bytecode?`,back:`Instruções de uma máquina virtual geradas a partir do código-fonte e executadas pelo interpretador.`}],"l2-listas":[{id:`l2-listas#1`,front:"O que `xs[::-1]` faz?",back:`Devolve uma cópia invertida da lista.`},{id:`l2-listas#2`,front:`Como copiar uma lista?`,back:`xs.copy(), xs[:] ou list(xs).`},{id:`l2-listas#3`,front:`Qual erro aparece ao acessar um índice que não existe?`,back:`IndexError: list index out of range.`}],"l2-dicionarios":[{id:`l2-dicionarios#1`,front:`Como ler uma chave de dict sem risco de KeyError?`,back:`d.get(chave, valor_padrao).`},{id:`l2-dicionarios#2`,front:`Quando usar um set?`,back:`Para elementos únicos e testes de pertencimento rápidos.`},{id:`l2-dicionarios#3`,front:`O que pode ser chave de dict?`,back:`Valores imutáveis (hashable): str, int, float, tuple de imutáveis.`}],"l2-strings":[{id:`l2-strings#1`,front:"O que acontece com s depois de `s.upper()` sem atribuição?",back:`Nada: strings são imutáveis; o resultado precisa ser guardado.`},{id:`l2-strings#2`,front:`Como transformar "a,b,c" em ["a","b","c"]?`,back:`"a,b,c".split(",")`}],"l2-arquivos":[{id:`l2-arquivos#1`,front:"Por que usar `with` ao abrir arquivos?",back:`Garante que o arquivo seja fechado, mesmo se ocorrer uma exceção.`},{id:`l2-arquivos#2`,front:`Por que sempre passar encoding="utf-8"?`,back:`Porque o padrão varia entre sistemas operacionais e causa erros de acentuação.`}],"l2-erros-excecoes":[{id:`l2-erros-excecoes#1`,front:`Como ler um traceback?`,back:`De baixo para cima: tipo e mensagem na última linha, depois o local, depois quem chamou.`},{id:`l2-erros-excecoes#2`,front:`Diferença entre ValueError e TypeError?`,back:`TypeError: tipo inadequado. ValueError: tipo certo, valor inválido.`},{id:`l2-erros-excecoes#3`,front:`Quando o bloco else de um try executa?`,back:`Quando nenhuma exceção ocorreu no try.`}],"l2-debugging":[{id:`l2-debugging#1`,front:`Quais são os passos da depuração sistemática?`,back:`Reproduzir, isolar, formular hipótese, experimentar, corrigir e prevenir com um teste.`},{id:`l2-debugging#2`,front:`O que é rubber duck debugging?`,back:`Explicar o código linha a linha em voz alta para encontrar o erro.`}],"l2-modulos":[{id:`l2-modulos#1`,front:`Para que serve um ambiente virtual?`,back:`Isolar as dependências (e versões) de cada projeto.`},{id:`l2-modulos#2`,front:'O que faz `if __name__ == "__main__":`?',back:`Executa o bloco só quando o arquivo é rodado diretamente, não quando importado.`}],"l2-testes":[{id:`l2-testes#1`,front:`Quais são as etapas do TDD?`,back:`Red (teste falhando), green (código mínimo para passar), refactor.`},{id:`l2-testes#2`,front:`O que são classes de equivalência?`,back:`Grupos de entradas que o programa deve tratar da mesma forma; testa-se um representante de cada.`},{id:`l2-testes#3`,front:`O que é uma regressão?`,back:`Um bug que reaparece após ter sido corrigido.`}],"l3-arrays":[{id:`l3-arrays#1`,front:`Por que inserir no início de uma lista é O(n)?`,back:`Porque todos os elementos precisam se deslocar uma posição.`},{id:`l3-arrays#2`,front:`O que significa append ser O(1) amortizado?`,back:`Às vezes custa O(n) (realocação), mas a média ao longo de muitas operações é constante.`}],"l3-crescimento-amortizado":[{id:`l3-crescimento-amortizado#1`,front:`Começando com capacidade 1 e dobrando, qual o limite para o total de cópias em n appends, e por quê?`,back:`Menos de 2n: as cópias são 1 + 2 + 4 + … + 2^k com 2^k < n, e essa soma é 2^(k+1) − 1. Com as n escritas, menos de 3n.`},{id:`l3-crescimento-amortizado#2`,front:`Por que crescer a capacidade de k em k deixa n appends em O(n²)?`,back:`São cerca de n/k realocações, copiando k, 2k, 3k, … elementos: a soma fica perto de n²/(2k). O k só divide a constante.`},{id:`l3-crescimento-amortizado#3`,front:`Qual a diferença entre custo amortizado e caso médio?`,back:`Amortizado é o custo total de qualquer sequência dividido pelo número de operações, sem probabilidade. Caso médio é a média sobre entradas sorteadas.`},{id:`l3-crescimento-amortizado#4`,front:`Por que uma lista dinâmica não deve encolher assim que fica com metade da capacidade em uso?`,back:`Alternar append e pop na fronteira faria crescer e encolher a cada operação, O(n) cada. Encolher só abaixo de 1/4 deixa folga (histerese).`},{id:`l3-crescimento-amortizado#5`,front:"Qual a diferença de custo entre `xs += [v]` e `xs = xs + [v]` dentro de um laço?",back:"`+=` estende a mesma lista: O(1) amortizado por passo. `xs + [v]` cria uma lista nova copiando tudo: O(n) por passo, O(n²) no laço."},{id:`l3-crescimento-amortizado#6`,front:`No método contábil para a lista que dobra, quanto cada append paga e para quê?`,back:`3 moedas: 1 pela própria escrita e 2 guardadas, que somadas pagam a cópia de todos os elementos na próxima realocação.`}],"l3-dois-ponteiros":[{id:`l3-dois-ponteiros#1`,front:`Na soma alvo com dois ponteiros convergentes (lista ordenada), se xs[i] + xs[j] < alvo, por que é seguro descartar i?`,back:`Porque xs[i] somado a qualquer elemento até j dá no máximo xs[i] + xs[j], que já é pequeno demais: nenhum par com i ainda pode dar certo.`},{id:`l3-dois-ponteiros#2`,front:`Qual é o invariante do padrão leitor e escritor?`,back:`xs[:escrita] contém exatamente os elementos mantidos entre os já lidos, na ordem original (e escrita nunca passa de leitura).`},{id:`l3-dois-ponteiros#3`,front:`O que dá errado ao remover itens de uma lista dentro de um for sobre ela?`,back:`Os elementos seguintes se deslocam para a esquerda e o for avança a posição, então alguns são pulados; além disso, cada remove custa O(n).`},{id:`l3-dois-ponteiros#4`,front:`Qual o custo de intercalar duas listas ordenadas de tamanhos n e m, e por quê?`,back:`O(n + m): cada passo coloca um elemento na saída e nenhum índice volta.`},{id:`l3-dois-ponteiros#5`,front:`No problema da maior área, qual tábua você descarta a cada passo e por quê?`,back:`A mais baixa das duas pontas: qualquer par dela com uma tábua mais interna é mais estreito e tem altura limitada por ela, então não supera a área atual.`},{id:`l3-dois-ponteiros#6`,front:`Por que dois ponteiros é O(n) e não O(n²)?`,back:`Cada passo move pelo menos um índice, sempre no mesmo sentido; o total de passos é limitado pelo tamanho da entrada.`}],"l3-pilhas-filas":[{id:`l3-pilhas-filas#1`,front:`LIFO ou FIFO: pilha?`,back:`LIFO (last in, first out).`},{id:`l3-pilhas-filas#2`,front:`Por que não usar list.pop(0) como fila?`,back:`Porque é O(n): desloca todos os elementos. Use deque.popleft(), que é O(1).`},{id:`l3-pilhas-filas#3`,front:`Que estrutura verifica parênteses balanceados?`,back:`Uma pilha.`}],"l3-expressoes-rpn":[{id:`l3-expressoes-rpn#1`,front:"Converta `(2 + 3) - 4` e `2 + 3 - 4` para RPN.",back:"Os dois viram `2 3 + 4 -`: `+` e `-` têm a mesma precedência e se agrupam à esquerda, então `2 + 3 - 4` já é `(2 + 3) - 4` e os parênteses não mudam nada."},{id:`l3-expressoes-rpn#2`,front:"Quanto vale `8 - 3 - 2` em Python, e por quê?",back:`3: operadores de mesma precedência se agrupam à esquerda, então é (8 - 3) - 2.`},{id:`l3-expressoes-rpn#3`,front:"Quanto vale `2 ** 3 ** 2` em Python, e por quê?",back:"512: `**` é associativo à direita, então é `2 ** (3 ** 2)`, ou seja, `2 ** 9`."},{id:`l3-expressoes-rpn#4`,front:"No pátio de manobras, o que acontece quando chega um `)`?",back:"Desempilha operadores para a saída até achar o `(`; depois descarta os dois parênteses."},{id:`l3-expressoes-rpn#5`,front:"No laço dos operadores, por que `>=` e não `>`?",back:"O `>=` faz o operador da esquerda sair no empate, o que implementa a associatividade à esquerda."},{id:`l3-expressoes-rpn#6`,front:`Por que o pátio de manobras é O(n)?`,back:`Cada token entra e sai da pilha no máximo uma vez.`},{id:`l3-expressoes-rpn#7`,front:`Ao converter infixa para RPN, o que muda de lugar: números ou operadores?`,back:`Só os operadores. Os números mantêm a ordem original.`}],"l3-filas-prioridade":[{id:`l3-filas-prioridade#1`,front:`O que uma fila de prioridade devolve quando você retira um item?`,back:`O mais prioritário (em Python, o de menor chave), não o mais antigo.`},{id:`l3-filas-prioridade#2`,front:`Quanto custam heappush e heappop num heap com n itens? E espiar o menor?`,back:"O(log n) cada um; espiar `h[0]` é O(1)."},{id:`l3-filas-prioridade#3`,front:`Depois de heapify, que posição da lista tem garantia?`,back:"Só `h[0]`, que é o menor. O resto não está ordenado."},{id:`l3-filas-prioridade#4`,front:`Por que guardar (prioridade, contador, item) em vez de (prioridade, item)?`,back:"O contador desempata pela ordem de chegada (fila estável) e impede que itens sem `<`, como dicts, sejam comparados."},{id:`l3-filas-prioridade#5`,front:`Como fazer "maior primeiro" com heapq?`,back:`Inserir a chave com o sinal trocado (-valor) e trocar de novo ao retirar.`},{id:`l3-filas-prioridade#6`,front:`Para manter os k maiores de um fluxo, que heap usar e de que tamanho?`,back:`Um heap mínimo de tamanho k: a raiz é o menor dos k maiores e decide quem entra.`},{id:`l3-filas-prioridade#7`,front:`Uma fila comum (FIFO) é uma fila de prioridade em que a prioridade é…?`,back:`A hora de chegada: quem chegou antes sai antes.`},{id:`l3-filas-prioridade#8`,front:`Quando não vale a pena usar fila de prioridade?`,back:`Quando todos os itens chegam antes da primeira retirada: basta ordenar uma vez.`}],"l3-hash":[{id:`l3-hash#1`,front:`Como uma tabela hash encontra a posição de uma chave?`,back:`Calcula hash(chave) % número_de_buckets.`},{id:`l3-hash#2`,front:`O que é uma colisão?`,back:`Duas chaves diferentes mapeadas para a mesma posição.`},{id:`l3-hash#3`,front:`Por que uma lista não pode ser chave de dict?`,back:`Porque é mutável: seu hash poderia mudar depois de inserida.`}],"l3-enderecamento-aberto":[{id:`l3-enderecamento-aberto#1`,front:`Numa tabela com sondagem linear, quando uma busca pode concluir que a chave não existe?`,back:`Quando chega a uma posição vazia (nunca usada). Lápides não param a busca.`},{id:`l3-enderecamento-aberto#2`,front:`Por que remover não pode simplesmente pôr None na posição?`,back:`Quebraria o caminho: buscas por chaves que passaram por ali parariam no vazio e diriam que elas não existem.`},{id:`l3-enderecamento-aberto#3`,front:`Ao inserir, por que não gravar na primeira lápide assim que ela aparece?`,back:`A chave pode existir mais adiante; é preciso ir até achá-la ou chegar a um vazio, senão ela fica duplicada.`},{id:`l3-enderecamento-aberto#4`,front:`Qual o custo esperado de uma busca sem sucesso com sondagem linear, em função de α?`,back:`≈ ½(1 + 1/(1 − α)²): 2,5 com α = 0,5; 5 com α = 2/3; 50 com α = 0,9.`},{id:`l3-enderecamento-aberto#5`,front:`Até que ocupação o dict do CPython vai antes de reconstruir?`,back:`2/3 das posições.`},{id:`l3-enderecamento-aberto#6`,front:`Quantas chaves aleatórias dão 50% de chance de colisão numa tabela de m posições?`,back:`Cerca de 1,2·√m (23 para m = 365, o paradoxo do aniversário).`},{id:`l3-enderecamento-aberto#7`,front:`Quando a reconstrução pode manter o mesmo tamanho?`,back:`Quando a ocupação vem quase toda de lápides: há poucas chaves vivas, e reconstruir só limpa as lápides.`}],"l3-chaves-hash":[{id:`l3-chaves-hash#1`,front:`Qual é a única regra obrigatória entre __eq__ e __hash__?`,back:`Se a == b, então hash(a) == hash(b).`},{id:`l3-chaves-hash#2`,front:`Hashes iguais garantem chaves iguais?`,back:`Não. Isso é uma colisão, permitida; quem decide é o ==.`},{id:`l3-chaves-hash#3`,front:`O que acontece com uma classe que define __eq__ e não define __hash__?`,back:`O Python faz __hash__ = None: a classe fica sem hash, e usá-la como chave dá TypeError (unhashable type).`},{id:`l3-chaves-hash#4`,front:`Uma chave muda depois de entrar no dict. Por que as buscas falham?`,back:`Ela ficou na posição do hash antigo. A busca pelo objeto parte do hash novo; a busca por um objeto igual ao antigo chega lá, mas o == falha.`},{id:`l3-chaves-hash#5`,front:`Quanto vale {1: "a", True: "b"}?`,back:`{1: "b"}: 1 == True e os dois têm o mesmo hash. Fica a primeira chave, com o último valor.`},{id:`l3-chaves-hash#6`,front:`Por que a soma dos códigos das letras é uma função hash ruim?`,back:`Ignora a ordem (todo anagrama colide) e gera poucos valores para palavras curtas.`},{id:`l3-chaves-hash#7`,front:`No Two Sum com índices, o que é chave e o que é valor do dict?`,back:`Chave: número já visto. Valor: o índice dele. Para cada x, procura alvo − x antes de guardar x.`},{id:`l3-chaves-hash#8`,front:`Como contar em O(n) os trechos contíguos com soma k?`,back:`Dict de somas acumuladas → quantas vezes apareceram, começando com {0: 1}; para cada soma S, some vezes[S − k].`}],"l3-arvores":[{id:`l3-arvores#1`,front:`Qual percurso de uma BST produz os valores em ordem crescente?`,back:`O percurso em ordem (in-order): esquerda, nó, direita.`},{id:`l3-arvores#2`,front:`Quando uma BST simples degenera?`,back:`Quando os valores são inseridos já ordenados: vira uma cadeia e a busca fica O(n).`}],"l3-arvores-balanceadas":[{id:`l3-arvores-balanceadas#1`,front:`O que uma rotação preserva e o que ela muda?`,back:`Preserva a ordem do percurso em ordem (a regra da BST). Muda a raiz da subárvore, as profundidades e, possivelmente, a altura.`},{id:`l3-arvores-balanceadas#2`,front:`Qual é o invariante de uma AVL?`,back:`Em todo nó, |altura(esq) − altura(dir)| ≤ 1, ou seja, fator de balanceamento −1, 0 ou +1.`},{id:`l3-arvores-balanceadas#3`,front:`Como reconhecer o caso LR e como consertá-lo?`,back:`fb(nó) = +2 e fb(filho esquerdo) < 0 (zigue-zague). Rotação à esquerda no filho esquerdo e depois rotação à direita no nó.`},{id:`l3-arvores-balanceadas#4`,front:`Por que a altura de uma AVL é O(log n)?`,back:`O menor número de nós de uma AVL de altura h segue N(h) = 1 + N(h − 1) + N(h − 2), que cresce exponencialmente (como Fibonacci); logo h ≈ 1,44 · log₂ n no pior caso.`},{id:`l3-arvores-balanceadas#5`,front:`Quantos consertos uma inserção numa AVL exige? E uma remoção?`,back:`Inserção: um só (no máximo 2 rotações), pois a subárvore volta à altura antiga. Remoção: pode exigir rotações em vários níveis, até O(log n).`},{id:`l3-arvores-balanceadas#6`,front:`Ao remover de uma BST um nó com dois filhos, quem toma o lugar dele?`,back:`O sucessor: o menor valor da subárvore direita (um passo à direita e depois sempre à esquerda). Depois, o sucessor é removido lá de baixo.`},{id:`l3-arvores-balanceadas#7`,front:`Qual a altura máxima de uma rubro-negra com n nós, e onde ela é usada?`,back:`No máximo 2 · log₂(n + 1). TreeMap e TreeSet do Java, std::map nas implementações comuns de C++, kernel Linux.`},{id:`l3-arvores-balanceadas#8`,front:`O Python tem árvore balanceada na biblioteca padrão? O que usar no lugar?`,back:`Não. dict e set para busca exata; lista ordenada com bisect (ou o pacote sortedcontainers) quando a ordem importa.`}],"l3-heap-binario":[{id:`l3-heap-binario#1`,front:`Num heap em lista (índices a partir de 0), onde estão os filhos e o pai do índice i?`,back:`Filhos em 2i + 1 e 2i + 2; pai em (i − 1) // 2.`},{id:`l3-heap-binario#2`,front:`Qual a diferença entre a regra da BST e a regra do heap mínimo?`,back:`BST: esquerda < nó < direita (busca qualquer valor em O(h)). Heap: pai ≤ filhos, ordem só vertical (mínimo em O(1), mas buscar um valor qualquer é O(n)).`},{id:`l3-heap-binario#3`,front:`Como funciona a inserção num heap, e quanto custa?`,back:`Coloca no fim da lista e sobe trocando com o pai enquanto for menor que ele: O(log n).`},{id:`l3-heap-binario#4`,front:`Ao retirar o mínimo, por que o elemento que desce troca com o MENOR dos filhos?`,back:`Porque quem sobe vira pai do outro filho; só o menor dos dois garante pai ≤ filho.`},{id:`l3-heap-binario#5`,front:`Por que construir um heap de baixo para cima custa O(n)?`,back:`Cada nó desce no máximo a sua altura, e a maioria dos nós está perto das folhas: metade não desce nada, um quarto desce no máximo 1... a soma não passa de n.`},{id:`l3-heap-binario#6`,front:`Por que a altura de um heap nunca degenera, ao contrário da BST?`,back:`Porque a forma é sempre uma árvore binária completa: altura ⌊log₂ n⌋, qualquer que seja a ordem de chegada.`},{id:`l3-heap-binario#7`,front:`Ao remover um elemento do meio do heap, o que pode acontecer com o substituto que veio do fim?`,back:`Ele pode precisar descer (se for maior que um filho) ou subir (se for menor que o novo pai), pois veio de outro ramo.`},{id:`l3-heap-binario#8`,front:`Quais as garantias e os pontos fracos do heapsort?`,back:`O(n log n) no pior caso e memória extra O(1); não é estável e aproveita mal o cache, então costuma perder para merge sort e quick sort bem implementados.`}],"l3-grafos":[{id:`l3-grafos#1`,front:`Que estrutura a BFS usa? E a DFS?`,back:`BFS usa fila; DFS usa pilha (ou recursão).`},{id:`l3-grafos#2`,front:`Qual o custo de BFS/DFS com lista de adjacência?`,back:`O(V + E).`},{id:`l3-grafos#3`,front:`Por que marcar vértices visitados?`,back:`Para não visitar de novo e não entrar em loop em grafos com ciclos.`}],"l3-grafos-dfs":[{id:`l3-grafos-dfs#1`,front:`Quanta memória ocupam a lista de adjacência e a matriz de adjacência?`,back:`Lista: O(V + E). Matriz: O(V²), seja qual for o número de arestas.`},{id:`l3-grafos-dfs#2`,front:`Em que situação a matriz de adjacência é a melhor escolha?`,back:`Grafo pequeno ou denso (E da ordem de V²), quando a pergunta "existe aresta u–v?" em O(1) domina ou o algoritmo trabalha com tabelas.`},{id:`l3-grafos-dfs#3`,front:`Num grafo não direcionado em lista de adjacência, quanto vale a soma dos tamanhos de todas as listas?`,back:`2E: cada aresta aparece na lista das duas pontas (a soma dos graus é 2E).`},{id:`l3-grafos-dfs#4`,front:`Numa grade, que conferência evita ligar a primeira linha à última sem querer, em Python?`,back:`Conferir 0 <= linha < R e 0 <= coluna < C antes de acessar: índice negativo não dá erro, pega o fim da lista.`},{id:`l3-grafos-dfs#5`,front:`Por que contar componentes com uma DFS a partir de cada vértice não visitado custa O(V + E), e não O(V · (V + E))?`,back:`Porque o conjunto de visitados é compartilhado: cada vértice é marcado uma vez e cada lista de vizinhos é percorrida uma vez, somando todas as DFS.`},{id:`l3-grafos-dfs#6`,front:`O que significam branco, cinza e preto na detecção de ciclos?`,back:`Branco: não descoberto. Cinza: entrou e não saiu (está no caminho atual da recursão). Preto: saiu, com tudo o que alcança já explorado.`},{id:`l3-grafos-dfs#7`,front:`Num grafo direcionado, que aresta encontrada pela DFS prova que existe ciclo? E por que "já visitado" não basta?`,back:`Uma aresta para um vértice cinza (aresta de retorno). Um vértice preto pode ser alcançado por dois caminhos sem ciclo nenhum, como no losango.`},{id:`l3-grafos-dfs#8`,front:`Qual o limite padrão de recursão do Python e o que fazer numa DFS em grafo grande?`,back:`Cerca de 1000 chamadas; trocar a recursão por uma pilha explícita (ou usar BFS).`}],"l3-union-find":[{id:`l3-union-find#1`,front:`Quais são as duas operações do Union-Find e o que cada uma responde?`,back:`find(x): qual é o representante (a raiz) do grupo de x. union(x, y): junta os grupos de x e y. "Estão ligados?" é find(x) == find(y).`},{id:`l3-union-find#2`,front:`Por que a união por tamanho limita a altura a log₂ n?`,back:`Um elemento só desce um nível quando o grupo dele é pendurado num grupo pelo menos do mesmo tamanho; o grupo dele dobra a cada descida, e isso só cabe log₂ n vezes.`},{id:`l3-union-find#3`,front:`O que a compressão de caminho faz, e quem ela não alcança?`,back:`No find, depois de achar a raiz, faz cada elemento do caminho apontar direto para ela. Elementos fora do caminho de algum find continuam onde estavam.`},{id:`l3-union-find#4`,front:`Qual o custo do Union-Find com união por tamanho e compressão de caminho?`,back:`O(α(n)) amortizado por operação, em que α é a inversa da função de Ackermann (no máximo 4 na prática): quase constante.`},{id:`l3-union-find#5`,front:`Como o Union-Find detecta que uma nova aresta fecha um ciclo num grafo não direcionado?`,back:`Se as duas pontas já têm o mesmo representante antes da união, a aresta é redundante: fecha um ciclo.`},{id:`l3-union-find#6`,front:`Por que union precisa ligar as raízes, e não os próprios x e y? E por que comparar os tamanhos das raízes?`,back:`Mudar o pai de x (que não é raiz) o separa do resto do grupo; ligar as raízes junta os grupos inteiros. E o tamanho só é mantido atualizado nas raízes.`},{id:`l3-union-find#7`,front:`Cite três coisas que o Union-Find não faz.`,back:`Não remove ligações (não desune), não mostra o caminho entre dois elementos e não responde alcance em grafos direcionados.`},{id:`l3-union-find#8`,front:`Num problema de grade em que se pergunta se a linha de cima alcança a de baixo, qual o truque para não testar todos os pares?`,back:`Criar dois elementos virtuais, um unido a toda a linha de cima e outro a toda a de baixo, e perguntar se os dois estão no mesmo grupo.`}],"l4-big-o":[{id:`l4-big-o#1`,front:`Qual a complexidade de dois loops aninhados sobre n?`,back:`O(n²).`},{id:`l4-big-o#2`,front:`O que significa O(log n)?`,back:`O trabalho cresce com o logaritmo: dobrar a entrada acrescenta um passo.`},{id:`l4-big-o#3`,front:`Por que Big O ignora constantes?`,back:`Porque descreve o crescimento para n grande, independentemente da máquina.`}],"l4-o-omega-teta":[{id:`l4-o-omega-teta#1`,front:`O que significa f(n) = O(g(n)), com as constantes?`,back:`Existem c > 0 e n₀ tais que f(n) ≤ c·g(n) para todo n ≥ n₀: f cresce no máximo como g.`},{id:`l4-o-omega-teta#2`,front:`Qual a diferença entre Ω e Θ?`,back:`Ω é limite inferior (f(n) ≥ c·g(n) a partir de n₀). Θ é O e Ω ao mesmo tempo: o crescimento exato, a menos de constantes.`},{id:`l4-o-omega-teta#3`,front:`Por que "O é o pior caso e Ω é o melhor caso" está errado?`,back:`O, Ω e Θ são limites e servem para qualquer função. Pior, melhor e caso médio são funções diferentes: o pior caso da busca linear, por exemplo, é O(n), Ω(n) e Θ(n).`},{id:`l4-o-omega-teta#4`,front:`Por que log₂ n e log₁₀ n são da mesma classe, mas 2ⁿ e 3ⁿ não?`,back:`Os logs diferem por um fator constante (log₂ n ≈ 3,32 · log₁₀ n). Já 3ⁿ / 2ⁿ = 1,5ⁿ cresce sem limite.`},{id:`l4-o-omega-teta#5`,front:`Quanto custa um laço externo em que i dobra (1, 2, 4, … < n) com um laço interno de i voltas?`,back:`Θ(n): 1 + 2 + 4 + … + 2ᵏ < 2n. A soma geométrica é dominada pelo maior termo.`},{id:`l4-o-omega-teta#6`,front:`Quanto custa visitar, para cada i de 1 a n, os índices de range(0, n, i)?`,back:`Θ(n log n): n/1 + n/2 + … + n/n é n vezes a série harmônica, que cresce como ln n.`}],"l4-analise-amortizada":[{id:`l4-analise-amortizada#1`,front:`No contador binário, por que n incrementos custam menos que 2n trocas, se um incremento pode trocar k bits?`,back:`O bit j só troca a cada 2ʲ incrementos: o total é n + n/2 + n/4 + … < 2n (método agregado).`},{id:`l4-analise-amortizada#2`,front:`Na fila com duas pilhas, quando a entrada é despejada na saída, e por que desenfileirar é O(1) amortizado?`,back:`Só quando a saída está vazia. Cada elemento é transferido no máximo uma vez (nada volta para a entrada), então cada um custa no máximo 4 operações de pilha em toda a vida.`},{id:`l4-analise-amortizada#3`,front:`Qual a fórmula do custo amortizado no método do potencial, e que condições Φ precisa cumprir?`,back:`Amortizado = real + (Φ depois − Φ antes), com Φ começando em 0 e nunca negativa; assim a soma dos amortizados limita a soma dos reais.`},{id:`l4-analise-amortizada#4`,front:`Por que a pilha monotônica é Θ(n) mesmo com um while dentro do for?`,back:`Cada índice é empilhado uma vez e desempilhado no máximo uma vez: o total de pops é menor que n, por mais que uma volta desempilhe muito.`},{id:`l4-analise-amortizada#5`,front:`Dê um exemplo de operação que quebra uma garantia amortizada, e por quê.`,back:`Decrementar no contador binário: alternando incremento e decremento entre 0111…1 e 1000…0, cada operação troca k bits, Θ(n·k). O decremento recria a situação cara sem ninguém ter pago por ela.`},{id:`l4-analise-amortizada#6`,front:`No máximo de janela deslizante com deque, por que é mais simples guardar índices do que valores?`,back:`Com o índice, dá para ver direto se o candidato da frente ficou para trás da janela (índice ≤ i − k) e retirá-lo. Guardando só valores, seria preciso comparar com o valor que saiu e manter os repetidos no deque.`}],"l4-busca":[{id:`l4-busca#1`,front:`Qual a pré-condição da busca binária?`,back:`A sequência precisa estar ordenada.`},{id:`l4-busca#2`,front:`Qual a invariante da busca binária?`,back:`Se o alvo existe, ele está no intervalo [lo, hi].`}],"l4-bisect-fronteiras":[{id:`l4-bisect-fronteiras#1`,front:"O que `bisect_left(xs, x)` devolve, descrito como fronteira de um predicado?",back:`A primeira posição i com xs[i] >= x, ou len(xs) se não houver: o limite inferior.`},{id:`l4-bisect-fronteiras#2`,front:`Como contar em O(log n) quantas vezes x aparece numa lista ordenada?`,back:`bisect_right(xs, x) − bisect_left(xs, x). Dá 0 se x não estiver.`},{id:`l4-bisect-fronteiras#3`,front:"No molde semiaberto, por que o ramo verdadeiro faz `hi = meio`, e por que isso não trava o laço?",back:`Porque o meio pode ser a própria fronteira. Como lo < hi e o meio é arredondado para baixo, meio < hi: o intervalo encolhe mesmo assim.`},{id:`l4-bisect-fronteiras#4`,front:"Numa tabela de faixas, quando usar `bisect_left` e quando usar `bisect_right`?",back:`"Até X" (o limite é o último valor da faixa): bisect_left nos limites. "A partir de X" (o corte é o primeiro valor da faixa): bisect_right nos cortes.`},{id:`l4-bisect-fronteiras#5`,front:`Como achar o maior valor ≤ x (o piso) numa lista ordenada, e qual a armadilha?`,back:`i = bisect_right(xs, x) − 1. Se i == −1 não existe piso, e xs[−1] devolveria o último elemento sem dar erro.`},{id:`l4-bisect-fronteiras#6`,front:"Quanto custa `insort`, e por quê?",back:`O(n): achar a posição é O(log n), mas inserir no meio da lista desloca todos os elementos seguintes.`},{id:`l4-bisect-fronteiras#7`,front:`Com q consultas em n itens, quando vale ordenar e usar bisect em vez de busca linear?`,back:`Quando q é grande: O((n + q) log n) contra O(q · n). Para uma consulta só, a busca linear ganha; para pertinência pura, set é melhor.`}],"l4-busca-na-resposta":[{id:`l4-busca-na-resposta#1`,front:`Que propriedade o verificador precisa ter para permitir busca binária na resposta?`,back:`Ser monotônico: percorrendo as respostas em ordem, ele muda de falso para verdadeiro (ou o contrário) uma única vez.`},{id:`l4-busca-na-resposta#2`,front:"No molde do máximo (V…V F…F), por que o meio é `(lo + hi + 1) // 2`?",back:`Porque o ramo verdadeiro faz lo = meio; com hi = lo + 1 e arredondamento para baixo, o meio seria o próprio lo e o laço não avançaria.`},{id:`l4-busca-na-resposta#3`,front:`Na capacidade mínima do caminhão, quais são lo e hi, e por quê?`,back:`lo = max(pesos), pois abaixo disso o pacote mais pesado nunca embarca; hi = sum(pesos), que despacha tudo num dia e é sempre viável.`},{id:`l4-busca-na-resposta#4`,front:`Quanto custa uma busca binária na resposta com verificador O(n)?`,back:`O(n · log(hi − lo)): no máximo ⌈log₂(hi − lo + 1)⌉ chamadas ao verificador.`},{id:`l4-busca-na-resposta#5`,front:`Por que o verificador deve perguntar "dias(C) ≤ D" e não "dias(C) == D"?`,back:`Porque == não é monotônico: com C grande os dias ficam abaixo de D e a resposta volta a ser falsa.`},{id:`l4-busca-na-resposta#6`,front:"Como calcular ⌈p / v⌉ com inteiros em Python, e por que evitar `math.ceil(p / v)`?",back:`(p + v − 1) // v, ou −(−p // v). p / v passa por float, que perde precisão com inteiros acima de 2⁵³.`},{id:`l4-busca-na-resposta#7`,front:`Como fazer busca binária quando a resposta é um número real?`,back:`meio = (lo + hi) / 2 com lo = meio ou hi = meio, por um número fixo de iterações (100, por exemplo), em vez de esperar o intervalo ficar menor que um epsilon.`}],"l4-ordenacao":[{id:`l4-ordenacao#1`,front:`O que é uma ordenação estável?`,back:`Uma que mantém a ordem relativa dos elementos com chaves iguais.`},{id:`l4-ordenacao#2`,front:`Pior caso do quicksort e quando acontece?`,back:`O(n²), quando o pivô é sempre o menor ou o maior (ex.: pivô fixo em lista já ordenada).`},{id:`l4-ordenacao#3`,front:`Por que merge sort é O(n log n)?`,back:`São log n níveis de divisão, e cada nível intercala n elementos no total.`}],"l4-quicksort":[{id:`l4-quicksort#1`,front:`O que a partição de Lomuto garante quando termina?`,back:`O pivô está na posição definitiva; à esquerda só há menores, à direita só maiores ou iguais, sem ordem dentro de cada lado.`},{id:`l4-quicksort#2`,front:`Qual recorrência descreve o quicksort quando o pivô cai sempre na ponta, e quanto ela dá?`,back:`T(n) = T(n − 1) + (n − 1), que soma n(n − 1)/2: Θ(n²).`},{id:`l4-quicksort#3`,front:`Se o pivô dividisse sempre em 10% e 90%, o quicksort ficaria quadrático?`,back:`Não: a recursão teria ≈ 6,6 · log₂ n níveis, com no máximo n comparações cada, ainda Θ(n log n).`},{id:`l4-quicksort#4`,front:`Qual a diferença entre o tempo esperado do quicksort aleatorizado e o caso médio do quicksort de pivô fixo?`,back:`O caso médio faz a média sobre entradas supostamente aleatórias; o tempo esperado faz a média sobre os sorteios do algoritmo e vale para qualquer entrada, inclusive ordenada.`},{id:`l4-quicksort#5`,front:`Por que o pivô aleatório não salva a partição de Lomuto numa lista cheia de valores iguais? O que salva?`,back:`Num trecho todo igual, qualquer pivô sorteado é igual aos outros, e Lomuto manda todos para o mesmo lado. Salvam a partição em três vias (<, =, >) e a de Hoare.`},{id:`l4-quicksort#6`,front:`Como garantir pilha O(log n) no quicksort, mesmo no pior caso de tempo?`,back:`Fazer a recursão no lado menor e tratar o lado maior com um laço: cada chamada recursiva recebe no máximo metade do trecho.`},{id:`l4-quicksort#7`,front:`Na seleção rápida no lugar, a partição de xs[lo..hi] deixou o pivô na posição p, e k > p. O que muda para a próxima rodada: k, lo ou hi?`,back:`Só lo, que passa a p + 1. k continua igual, porque é uma posição da lista inteira e o pivô já está na posição definitiva.`}],"l4-ordenacao-linear":[{id:`l4-ordenacao-linear#1`,front:`Por que toda ordenação por comparação faz pelo menos log₂(n!) comparações no pior caso?`,back:`A árvore de decisão precisa de uma folha para cada uma das n! ordens, e uma árvore binária de altura h tem no máximo 2ʰ folhas: 2ʰ ≥ n!.`},{id:`l4-ordenacao-linear#2`,front:`Por que é impossível ordenar 3 elementos com no máximo 2 comparações?`,back:`2 comparações distinguem no máximo 2² = 4 casos, e 3 elementos têm 3! = 6 ordens possíveis.`},{id:`l4-ordenacao-linear#3`,front:`Por que o counting sort não contradiz o limite Ω(n log n)?`,back:`Ele não compara elementos: usa a chave como índice, e cada acesso cont[x] escolhe entre k possibilidades de uma vez.`},{id:`l4-ordenacao-linear#4`,front:`Quanto custa o counting sort, e quando ele não compensa?`,back:`Θ(n + k), com k a faixa das chaves. Não compensa quando k é muito maior que n, como CPFs tratados como inteiros.`},{id:`l4-ordenacao-linear#5`,front:`Em que ordem o radix sort LSD processa os dígitos, e que propriedade cada passada precisa ter?`,back:`Do dígito menos significativo para o mais significativo; cada passada precisa ser estável.`},{id:`l4-ordenacao-linear#6`,front:`Quanto custa o radix sort LSD para n chaves de d dígitos na base b?`,back:`Θ(d · (n + b)).`},{id:`l4-ordenacao-linear#7`,front:`No counting sort com soma de prefixos inclusiva, por que a entrada é percorrida de trás para frente?`,back:`Porque cont[v] aponta para o fim da região da chave v; percorrendo de trás para frente, o último a chegar ocupa o fim da região e a ordem dos iguais é preservada.`}],"l4-recursao":[{id:`l4-recursao#1`,front:`Quais os dois elementos de toda função recursiva?`,back:`Caso base e passo recursivo que se aproxima dele.`},{id:`l4-recursao#2`,front:`O que é memoização?`,back:`Guardar resultados de chamadas já feitas para não recalcular.`},{id:`l4-recursao#3`,front:`Por que fib recursiva ingênua é lenta?`,back:`Recalcula os mesmos subproblemas repetidamente: crescimento exponencial.`}],"l4-dividir-conquistar":[{id:`l4-dividir-conquistar#1`,front:`Quais são as três etapas de um algoritmo de dividir para conquistar?`,back:`Dividir em subproblemas menores do mesmo tipo, resolver cada um recursivamente e combinar as respostas.`},{id:`l4-dividir-conquistar#2`,front:`Qual o custo de T(n) = 2T(n/2) + O(1), e por que dividir não acelerou nada?`,back:`O(n): a árvore tem 2n − 1 chamadas de custo constante, e as duas metades continuam sendo visitadas por inteiro.`},{id:`l4-dividir-conquistar#3`,front:`Como a árvore de recursão mostra que T(n) = 2T(n/2) + O(n) é O(n log n)?`,back:`Cada nível tem 2ᵏ chamadas de tamanho n/2ᵏ, somando n de trabalho, e há log₂ n níveis.`},{id:`l4-dividir-conquistar#4`,front:`Qual a profundidade da pilha numa recursão que corta o problema ao meio? E numa que tira um item por vez?`,back:`Cerca de log₂ n (21 quadros para um milhão); n quadros, que estouram o limite padrão do Python perto de 1 000.`},{id:`l4-dividir-conquistar#5`,front:`Por que uma busca binária recursiva que fatia a lista (xs[meio + 1:]) deixa de ser O(log n)?`,back:`Cada fatia copia O(n) elementos: a recorrência vira T(n) = T(n/2) + O(n) = O(n).`},{id:`l4-dividir-conquistar#6`,front:`Qual é o truque de Karatsuba e que custo ele atinge?`,back:`Obter ad + bc como (a + b)(c + d) − ac − bd: 3 produtos de metades em vez de 4, O(n^log₂3) ≈ O(n^1,585).`},{id:`l4-dividir-conquistar#7`,front:`Por que a seleção rápida custa O(n) esperado, e não O(n log n)?`,back:`Depois de separar os valores pelo pivô sorteado, ela continua só no grupo que contém a posição k: com cortes perto do meio, T(n) = T(n/2) + O(n), e n + n/2 + n/4 + … < 2n. Resolver os dois lados, como no merge sort, daria 2T(n/2) + O(n) = O(n log n).`}],"l4-backtracking":[{id:`l4-backtracking#1`,front:`Quais são os três passos do molde de backtracking, e por que o terceiro é necessário?`,back:`Escolher, explorar, desfazer. Desfazer devolve o estado compartilhado ao que era antes, para a chamada mãe tentar a próxima opção.`},{id:`l4-backtracking#2`,front:"Por que se registra `atual[:]` e não `atual`?",back:`atual é uma lista compartilhada que o backtracking esvazia ao voltar; sem cópia, todas as respostas apontam para a mesma lista, vazia no fim.`},{id:`l4-backtracking#3`,front:`Quantas folhas tem a árvore dos subconjuntos de n itens? E a das permutações? Qual a profundidade da pilha nas duas?`,back:`2ⁿ e n! folhas; a profundidade é n, o número de decisões.`},{id:`l4-backtracking#4`,front:`O que é podar, e em que isso difere da força bruta?`,back:`Abandonar uma solução parcial que já viola uma restrição, junto com todo o ramo abaixo dela; a força bruta monta todas as candidatas completas e só então testa.`},{id:`l4-backtracking#5`,front:`Por que a poda "soma parcial maior que o alvo" exige valores positivos?`,back:`Com negativos, uma soma acima do alvo ainda pode descer; o corte jogaria fora respostas válidas.`},{id:`l4-backtracking#6`,front:`Com valores repetidos e ordenados, como evitar gerar a mesma combinação duas vezes?`,back:`No mesmo nível, pular um valor igual ao anterior (j > inicio e vs[j] == vs[j − 1]); descendo um nível, o valor repetido continua disponível.`},{id:`l4-backtracking#7`,front:`Como as N rainhas testam ataques em diagonal em O(1)?`,back:`Casas da mesma diagonal têm o mesmo linha − coluna (uma direção) ou o mesmo linha + coluna (a outra); guardam-se esses valores em conjuntos.`}],"l4-pd-guloso":[{id:`l4-pd-guloso#1`,front:`Quais as duas propriedades que indicam PD?`,back:`Subproblemas sobrepostos e subestrutura ótima.`},{id:`l4-pd-guloso#2`,front:`Top-down × bottom-up?`,back:`Top-down: recursão com cache. Bottom-up: preencher a tabela dos menores para os maiores.`},{id:`l4-pd-guloso#3`,front:`Quando o guloso falha no problema do troco?`,back:`Quando o sistema de moedas não é "canônico", ex.: [1, 3, 4] para 6.`}],"l4-pd-mochila-lcs":[{id:`l4-pd-mochila-lcs#1`,front:`Na mochila 0/1, o que dp[i][c] representa e qual é a recorrência?`,back:`O maior valor usando só os i primeiros itens com capacidade c: max(dp[i − 1][c], valor_i + dp[i − 1][c − peso_i]), a segunda opção só quando peso_i ≤ c.`},{id:`l4-pd-mochila-lcs#2`,front:`Na mochila com uma linha só, em que sentido se percorre a capacidade, e o que acontece no outro sentido?`,back:`De W para baixo, para que dp[c − peso] ainda seja da linha anterior. De baixo para cima, o mesmo item entra várias vezes: vira a mochila ilimitada.`},{id:`l4-pd-mochila-lcs#3`,front:`Qual é a recorrência da LCS quando os últimos caracteres são iguais? E quando são diferentes?`,back:`Iguais: dp[i − 1][j − 1] + 1. Diferentes: max(dp[i − 1][j], dp[i][j − 1]).`},{id:`l4-pd-mochila-lcs#4`,front:`Como descobrir, olhando a tabela da mochila, se o item i entrou na solução?`,back:`Na capacidade c corrente, se dp[i][c] ≠ dp[i − 1][c], o item i entrou: anote-o, faça c −= peso_i e passe à linha i − 1.`},{id:`l4-pd-mochila-lcs#5`,front:`Por que Θ(n · W) não torna a mochila 0/1 um problema polinomial?`,back:`W ocupa só uns log₂ W bits na entrada; um custo proporcional a W é exponencial nesse tamanho (pseudopolinomial).`},{id:`l4-pd-mochila-lcs#6`,front:`Qual é o menor número de inserções e remoções que transforma a em b, em função da LCS?`,back:`m + n − 2 · LCS, com m e n os tamanhos de a e b.`},{id:`l4-pd-mochila-lcs#7`,front:`Quando o top-down leva vantagem sobre o bottom-up, e quando ele é perigoso em Python?`,back:`Quando poucos estados são alcançáveis (pesos grandes e espalhados). É perigoso quando a cadeia de dependências é longa: passa de ~1 000 níveis e dá RecursionError.`}],"l4-guloso-intervalos":[{id:`l4-guloso-intervalos#1`,front:`Qual regra gulosa resolve o escalonamento de intervalos, e quanto custa?`,back:`Ordenar pelo fim e aceitar cada pedido que começa a partir do fim do último aceito. O(n log n), por causa da ordenação.`},{id:`l4-guloso-intervalos#2`,front:`Dê um contraexemplo para "o mais curto primeiro" no escalonamento de intervalos.`,back:`[0, 5), [4, 6), [5, 10): a regra pega [4, 6), que colide com os outros dois; o ótimo é [0, 5) e [5, 10).`},{id:`l4-guloso-intervalos#3`,front:`Resuma o argumento de troca do escalonamento de intervalos.`,back:`Numa solução ótima, troque o primeiro pedido pelo que termina mais cedo de todos: ele termina antes ou junto, então não colide com os demais. Logo existe ótimo com a escolha gulosa.`},{id:`l4-guloso-intervalos#4`,front:`Qual é o menor número de salas para um conjunto de intervalos, e por que não dá para usar menos?`,back:`A profundidade: o maior número de intervalos num mesmo instante. Esses intervalos simultâneos precisam de salas diferentes.`},{id:`l4-guloso-intervalos#5`,front:`No particionamento de intervalos, em que ordem processar e como achar uma sala livre depressa?`,back:`Em ordem de início; uma heap com o horário em que cada sala fica livre diz se a que libera primeiro já está livre.`},{id:`l4-guloso-intervalos#6`,front:`A regra passou em 300 testes aleatórios contra a força bruta. Ela está certa?`,back:`Não necessariamente: "menos conflitos" passa em sorteios pequenos e tem contraexemplo com 11 intervalos. Só uma prova garante.`},{id:`l4-guloso-intervalos#7`,front:`Por que o guloso por valor/peso funciona na mochila fracionária e falha na 0/1?`,back:`Na fracionária dá para trocar um pedaço de item pior pelo mesmo peso de um melhor sem perder valor; na 0/1 os itens não se dividem.`},{id:`l4-guloso-intervalos#8`,front:`Como resolver intervalos com valores (weighted interval scheduling)?`,back:`PD em ordem de fim: melhor[j] = max(melhor[j − 1], valor_j + melhor[p(j)]), com p(j) achado por busca binária. O(n log n).`}],"l4-dijkstra":[{id:`l4-dijkstra#1`,front:`Qual estrutura o Dijkstra usa para escolher o próximo vértice?`,back:`Uma fila de prioridade (heap) pela menor distância.`},{id:`l4-dijkstra#2`,front:`Quando o Dijkstra pode falhar?`,back:`Com arestas de peso negativo.`}],"l4-ordenacao-topologica":[{id:`l4-ordenacao-topologica#1`,front:`O que é uma ordenação topológica, e quando ela existe?`,back:`Uma lista de todos os vértices em que toda aresta u → v tem u antes de v. Existe se e somente se o grafo direcionado não tem ciclo (é um DAG).`},{id:`l4-ordenacao-topologica#2`,front:`Quais são os passos do algoritmo de Kahn, e quanto ele custa?`,back:`Calcular os graus de entrada, pôr na fila os de grau 0 e, a cada vértice tirado, descontar 1 de cada vizinho, enfileirando quem chega a 0. O(V + E).`},{id:`l4-ordenacao-topologica#3`,front:`Como o Kahn revela que há um ciclo, e quem sobra?`,back:`A ordem termina com menos de V vértices. Sobram os vértices dos ciclos e todos os que dependem deles.`},{id:`l4-ordenacao-topologica#4`,front:`Como obter uma ordenação topológica com DFS?`,back:`Anotar a ordem em que os vértices terminam (pós-ordem) e invertê-la.`},{id:`l4-ordenacao-topologica#5`,front:`Por que uma BFS a partir das fontes erra o semestre de uma disciplina?`,back:`Ela usa o primeiro pré-requisito que alcança a disciplina, mas a disciplina precisa esperar o último: semestre = 1 + o maior semestre entre os pré-requisitos.`},{id:`l4-ordenacao-topologica#6`,front:`Como achar caminhos mínimos num DAG com pesos negativos, e a que custo?`,back:`Processar os vértices em ordem topológica, relaxando as arestas que saem de cada um: O(V + E), sem heap.`},{id:`l4-ordenacao-topologica#7`,front:`O que é o caminho crítico de um projeto?`,back:`A cadeia de tarefas dependentes de maior duração total. Ela define o prazo mínimo, e qualquer atraso nela atrasa o projeto (folga zero).`},{id:`l4-ordenacao-topologica#8`,front:`Quando é preciso usar Bellman-Ford em vez de relaxar em ordem topológica?`,back:`Quando o grafo tem ciclos e pesos negativos. Ele relaxa todas as arestas V − 1 vezes, O(V · E), e detecta ciclos negativos.`}],"l4-arvore-geradora-minima":[{id:`l4-arvore-geradora-minima#1`,front:`Quantas arestas tem uma árvore geradora de um grafo conexo com V vértices?`,back:`V − 1.`},{id:`l4-arvore-geradora-minima#2`,front:`O que diz a propriedade do corte, e como se prova?`,back:`A aresta mais barata que cruza um corte pode estar numa AGM. Prova por troca: numa AGM sem ela, o caminho entre as pontas cruza o corte por outra aresta, não mais barata, que pode ser trocada por ela.`},{id:`l4-arvore-geradora-minima#3`,front:`Como o Kruskal decide se aceita uma aresta, e quanto ele custa?`,back:`Percorre as arestas em ordem crescente de custo e aceita a que liga grupos diferentes do Union-Find (find(u) != find(v)). O(E log E), dominado pela ordenação.`},{id:`l4-arvore-geradora-minima#4`,front:`Qual é a única diferença entre o Prim e o Dijkstra com heap?`,back:`A prioridade: no Prim, o custo da aresta que liga o vértice à árvore; no Dijkstra, a distância total desde a origem.`},{id:`l4-arvore-geradora-minima#5`,front:`A AGM dá o caminho mais barato entre dois vértices? Por quê?`,back:`Não. Ela minimiza o custo total da rede; o caminho dentro da árvore pode ser mais caro que um atalho que ficou de fora.`},{id:`l4-arvore-geradora-minima#6`,front:`Somar a mesma constante a todos os custos muda a AGM? E o caminho mínimo?`,back:`A AGM não muda, porque toda árvore geradora tem V − 1 arestas e sobe o mesmo valor. O caminho mínimo pode mudar, porque caminhos com mais arestas sobem mais.`},{id:`l4-arvore-geradora-minima#7`,front:`Quando o Prim sem heap, O(V²), é a melhor escolha?`,back:`Em grafos densos, com E perto de V², como um grafo completo de pontos.`},{id:`l4-arvore-geradora-minima#8`,front:`Como dividir pontos em k grupos com o maior espaçamento possível?`,back:`Rodar o Kruskal sobre todos os pares e parar quando restarem k grupos; equivale a cortar as k − 1 arestas mais caras da AGM.`}],"l5-classes":[{id:`l5-classes#1`,front:`O que é self?`,back:`Referência ao próprio objeto sobre o qual o método foi chamado.`},{id:`l5-classes#2`,front:`Atributo de classe × de instância?`,back:`O de classe é compartilhado por todas as instâncias; o de instância pertence a cada objeto.`},{id:`l5-classes#3`,front:`Para que serve o encapsulamento?`,back:`Esconder detalhes internos e garantir que o objeto permaneça válido (invariantes).`}],"l5-heranca-composicao":[{id:`l5-heranca-composicao#1`,front:`Composição × herança: qual a regra prática?`,back:`Prefira composição; use herança quando "é um" for verdadeiro e a subclasse puder substituir a mãe.`},{id:`l5-heranca-composicao#2`,front:`O que é polimorfismo?`,back:`Objetos de tipos diferentes responderem à mesma interface, cada um à sua maneira.`}],"l5-solid-padroes":[{id:`l5-solid-padroes#1`,front:`O que diz o Open/Closed Principle?`,back:`Módulos devem ser abertos para extensão e fechados para modificação.`},{id:`l5-solid-padroes#2`,front:`Para que serve o padrão Observer?`,back:`Para notificar vários interessados quando um evento acontece, sem acoplá-los a quem emite.`},{id:`l5-solid-padroes#3`,front:`O que significa YAGNI?`,back:`"You aren't gonna need it": não implemente o que ainda não é necessário.`}],"l6-html-css":[{id:`l6-html-css#1`,front:`Por que usar <button> em vez de <div onclick>?`,back:`O button é focável, ativável por teclado e anunciado como botão por leitores de tela.`},{id:`l6-html-css#2`,front:`Qual a razão de contraste mínima para texto normal (WCAG AA)?`,back:`4,5:1.`},{id:`l6-html-css#3`,front:`Flexbox × Grid?`,back:`Flexbox para uma dimensão; Grid para layouts em duas dimensões.`}],"l6-javascript-dom":[{id:`l6-javascript-dom#1`,front:`Por que usar === em vez de ==?`,back:`Porque == faz conversões de tipo implícitas e surpreendentes.`},{id:`l6-javascript-dom#2`,front:`textContent × innerHTML?`,back:`textContent insere texto; innerHTML interpreta HTML (risco de XSS com dados do usuário).`},{id:`l6-javascript-dom#3`,front:`O que roda primeiro: Promise.then ou setTimeout(…, 0)?`,back:`Promise.then (microtask) roda antes do setTimeout (macrotask).`}],"l6-http-rest":[{id:`l6-http-rest#1`,front:`401 × 403?`,back:`401: não autenticado. 403: autenticado, mas sem permissão.`},{id:`l6-http-rest#2`,front:`Quais métodos HTTP são idempotentes?`,back:`GET, PUT, DELETE (e HEAD, OPTIONS). POST não é.`},{id:`l6-http-rest#3`,front:`O que é CORS?`,back:`Mecanismo pelo qual o servidor permite que páginas de outras origens leiam suas respostas no navegador.`}],"l6-backend-auth":[{id:`l6-backend-auth#1`,front:`Qual a diferença entre 401 e 403?`,back:`401: o servidor não sabe quem você é (não autenticado). 403: sabe, mas você não tem permissão.`},{id:`l6-backend-auth#2`,front:`Por que validar no servidor se o front-end já valida?`,back:`Porque qualquer um pode mandar requisições direto, sem passar pelo front-end. A validação do cliente é só conforto.`},{id:`l6-backend-auth#3`,front:`O que cada camada faz: rota, serviço, repositório?`,back:`Rota: traduz HTTP. Serviço: regras de negócio. Repositório: acesso ao banco.`},{id:`l6-backend-auth#4`,front:`Uma vantagem da sessão no servidor sobre o JWT?`,back:`Dá para encerrar a sessão na hora, apagando-a no servidor.`}],"l7-sql":[{id:`l7-sql#1`,front:`O que é uma chave estrangeira?`,back:`Coluna que referencia a chave primária de outra tabela, criando um relacionamento.`},{id:`l7-sql#2`,front:`WHERE × HAVING?`,back:`WHERE filtra linhas antes do GROUP BY; HAVING filtra grupos depois.`},{id:`l7-sql#3`,front:"Por que usar `?` em consultas no Python?",back:`Para passar valores como parâmetros e evitar SQL injection.`}],"l7-joins":[{id:`l7-joins#1`,front:`Como modelar muitos-para-muitos?`,back:`Com uma tabela associativa contendo as chaves estrangeiras das duas tabelas.`},{id:`l7-joins#2`,front:`INNER × LEFT JOIN?`,back:`INNER mantém só linhas com correspondência; LEFT mantém todas as da esquerda, com NULL quando não há par.`}],"l7-normalizacao-indices":[{id:`l7-normalizacao-indices#1`,front:`O que significa o A de ACID?`,back:`Atomicidade: a transação acontece por completo ou não acontece.`},{id:`l7-normalizacao-indices#2`,front:`Quando criar um índice?`,back:`Em colunas usadas com frequência em WHERE, JOIN ou ORDER BY, verificando com EXPLAIN.`},{id:`l7-normalizacao-indices#3`,front:`O que é a 3FN?`,back:`Nenhum atributo não-chave depende de outro atributo não-chave (sem dependências transitivas).`}],"l7-nosql-escala":[{id:`l7-nosql-escala#1`,front:`Diferença entre replicação e particionamento?`,back:`Replicação: cópias dos mesmos dados em várias máquinas. Particionamento: cada máquina guarda uma parte diferente.`},{id:`l7-nosql-escala#2`,front:`O que o teorema CAP realmente diz?`,back:`Durante uma partição de rede, é preciso escolher entre consistência e disponibilidade.`},{id:`l7-nosql-escala#3`,front:`Por que hash consistente?`,back:`Para que adicionar ou remover máquinas mova só uma fração pequena das chaves.`},{id:`l7-nosql-escala#4`,front:`Um bom uso de Redis?`,back:`Cache, sessões, contadores, filas: acesso rápido por chave, com expiração.`}],"l8-processos-threads":[{id:`l8-processos-threads#1`,front:`Processo × thread?`,back:`Processos têm memória isolada; threads de um processo compartilham a memória.`},{id:`l8-processos-threads#2`,front:`O que é uma troca de contexto?`,back:`Salvar o estado (registradores etc.) de um processo e restaurar o de outro para trocar quem usa a CPU.`},{id:`l8-processos-threads#3`,front:`Qual política minimiza o tempo médio de espera?`,back:`SJF (shortest job first), se as durações forem conhecidas.`}],"l8-memoria-arquivos":[{id:`l8-memoria-arquivos#1`,front:`Como se calcula o deslocamento de um endereço virtual com páginas de 4096 bytes?`,back:`endereço % 4096.`},{id:`l8-memoria-arquivos#2`,front:`O que é uma falta de página?`,back:`Acesso a uma página que não está mapeada na RAM naquele momento.`},{id:`l8-memoria-arquivos#3`,front:`Diferença entre pilha e heap?`,back:`Pilha: frames das chamadas, liberados ao retornar. Heap: objetos dinâmicos, liberados por free ou pelo coletor de lixo.`},{id:`l8-memoria-arquivos#4`,front:`O que é um inode?`,back:`A estrutura com os metadados de um arquivo e a localização dos seus blocos.`}],"l8-concorrencia":[{id:`l8-concorrencia#1`,front:"Por que `x += 1` não é seguro entre threads?",back:`Porque são várias operações (ler, somar, escrever) que podem ser intercaladas.`},{id:`l8-concorrencia#2`,front:`Como prevenir deadlocks de forma simples?`,back:`Adquirindo os locks sempre na mesma ordem.`}],"l9-camadas-tcp-udp":[{id:`l9-camadas-tcp-udp#1`,front:`Quais as etapas do three-way handshake?`,back:`SYN, SYN-ACK, ACK.`},{id:`l9-camadas-tcp-udp#2`,front:`TCP × UDP?`,back:`TCP: conexão confiável e ordenada. UDP: datagramas sem garantias e com menos latência.`},{id:`l9-camadas-tcp-udp#3`,front:`O que significa /24 em 192.168.0.0/24?`,back:`Que os primeiros 24 bits identificam a rede (máscara 255.255.255.0).`}],"l9-dns-https":[{id:`l9-dns-https#1`,front:`O que o TTL de um registro DNS controla?`,back:`Por quanto tempo a resposta pode ser mantida em cache.`},{id:`l9-dns-https#2`,front:`O que o TLS garante?`,back:`Confidencialidade, integridade e autenticidade do servidor.`}],"l9-sockets":[{id:`l9-sockets#1`,front:`TCP preserva as fronteiras de cada send()?`,back:`Não. Ele entrega um fluxo de bytes; a aplicação precisa enquadrar as mensagens.`},{id:`l9-sockets#2`,front:`Duas formas de enquadrar mensagens?`,back:`Delimitador (ex.: \\n) ou prefixo com o tamanho.`},{id:`l9-sockets#3`,front:`O que accept() devolve?`,back:`Um novo socket para conversar com aquele cliente, mais o endereço dele.`},{id:`l9-sockets#4`,front:`Vantagem da E/S assíncrona num servidor?`,back:`Uma thread atende muitas conexões, porque não fica parada esperando a rede.`}],"l10-git":[{id:`l10-git#1`,front:`Para que serve a staging area?`,back:`Escolher exatamente o que entra no próximo commit.`},{id:`l10-git#2`,front:`O que é uma branch no Git?`,back:`Um ponteiro móvel para um commit; uma linha de desenvolvimento independente.`},{id:`l10-git#3`,front:`Vazou um token num commit público. O que fazer?`,back:`Revogar o token imediatamente; apagar o commit não basta.`}],"l10-clean-code":[{id:`l10-clean-code#1`,front:`O que é refatoração?`,back:`Melhorar a estrutura do código sem alterar seu comportamento externo.`},{id:`l10-clean-code#2`,front:`O que comentários devem explicar?`,back:`O porquê de decisões que o código não deixa claro, não o quê.`}],"l10-testes-ci":[{id:`l10-testes-ci#1`,front:`O que é integração contínua?`,back:`Rodar automaticamente build e testes a cada mudança enviada ao repositório.`},{id:`l10-testes-ci#2`,front:`Por que 100% de cobertura não garante correção?`,back:`Porque código executado por um teste não significa comportamento verificado por asserts adequados.`}],"l10-arquitetura":[{id:`l10-arquitetura#1`,front:`O que diz a regra de dependência?`,back:`Camadas internas (domínio) não dependem das externas (web, banco); as dependências apontam para dentro.`},{id:`l10-arquitetura#2`,front:`Quatro partes de um ADR?`,back:`Título, contexto, decisão e consequências (geralmente também o status).`},{id:`l10-arquitetura#3`,front:`Quando microsserviços fazem sentido?`,back:`Quando há vários times que precisam implantar de forma independente ou partes com necessidades de escala muito diferentes.`},{id:`l10-arquitetura#4`,front:`Formato de uma história de usuário?`,back:`"Como <quem>, quero <o quê>, para <por quê>", com critérios de aceitação testáveis.`}],"l11-fundamentos":[{id:`l11-fundamentos#1`,front:`Por que não usar SHA-256 puro para senhas?`,back:`Porque é rápido demais (permite bilhões de tentativas por segundo) e sem salt é vulnerável a rainbow tables.`},{id:`l11-fundamentos#2`,front:`Para que serve o salt?`,back:`Para que senhas iguais tenham hashes diferentes e tabelas pré-calculadas não funcionem.`},{id:`l11-fundamentos#3`,front:`Autenticação × autorização?`,back:`Autenticação verifica a identidade; autorização verifica as permissões.`}],"l11-owasp":[{id:`l11-owasp#1`,front:`Qual a defesa principal contra SQL injection?`,back:`Consultas parametrizadas (prepared statements).`},{id:`l11-owasp#2`,front:`O que é XSS?`,back:`Injeção de scripts que executam no navegador de outros usuários.`},{id:`l11-owasp#3`,front:`Qual é a categoria nº 1 do OWASP Top 10?`,back:`Broken Access Control (falhas de controle de acesso).`}],"l11-criptografia":[{id:`l11-criptografia#1`,front:`Que propriedade o HMAC garante que o hash simples não garante?`,back:`Autenticidade: só quem tem a chave secreta consegue gerar a etiqueta correta.`},{id:`l11-criptografia#2`,front:`Por que usar hmac.compare_digest em vez de ==?`,back:`Para comparar em tempo constante e evitar ataques de temporização.`},{id:`l11-criptografia#3`,front:`No RSA, o que é público e o que é privado?`,back:`Público: (e, n). Privado: d (e os primos p e q).`},{id:`l11-criptografia#4`,front:`Como o HTTPS combina criptografia assimétrica e simétrica?`,back:`Usa a assimétrica para autenticar o servidor e combinar uma chave; cifra os dados com a simétrica, que é mais rápida.`}],"l12-linux-shell":[{id:`l12-linux-shell#1`,front:`O que significa chmod 755?`,back:`Dono rwx; grupo e outros r-x.`},{id:`l12-linux-shell#2`,front:"Por que ordenar antes de `uniq -c`?",back:`Porque uniq só agrupa linhas iguais adjacentes.`},{id:`l12-linux-shell#3`,front:`Diferença entre > e >>?`,back:`> sobrescreve o arquivo; >> acrescenta ao final.`}],"l12-docker":[{id:`l12-docker#1`,front:`Container × VM?`,back:`Container isola processos no mesmo kernel (leve); VM virtualiza hardware com um SO completo (pesada).`},{id:`l12-docker#2`,front:`Como persistir dados de um container?`,back:`Com volumes.`}],"l12-deploy-observabilidade":[{id:`l12-deploy-observabilidade#1`,front:`O que é orçamento de erros?`,back:`A quantidade de falhas permitida pelo SLO num período; quando acaba, a prioridade vira confiabilidade.`},{id:`l12-deploy-observabilidade#2`,front:`Por que usar percentis em vez da média para latência?`,back:`Porque a média esconde a cauda: poucos usuários muito lentos somem na média.`},{id:`l12-deploy-observabilidade#3`,front:`Os três sinais de observabilidade?`,back:`Logs, métricas e traces.`},{id:`l12-deploy-observabilidade#4`,front:`O que é um deploy canário?`,back:`Liberar a versão nova para uma fração pequena do tráfego e comparar com a antiga antes de liberar para todos.`}],"l13-ml-fundamentos":[{id:`l13-ml-fundamentos#1`,front:`Para que serve o conjunto de teste?`,back:`Para estimar, uma única vez no fim, o desempenho em dados nunca vistos.`},{id:`l13-ml-fundamentos#2`,front:`Precisão × recall?`,back:`Precisão: dos marcados como positivos, quantos são. Recall: dos positivos reais, quantos foram encontrados.`},{id:`l13-ml-fundamentos#3`,front:`O que o gradiente descendente faz?`,back:`Ajusta os parâmetros na direção oposta ao gradiente da perda, reduzindo o erro passo a passo.`}],"l13-redes-neurais":[{id:`l13-redes-neurais#1`,front:`O que a retropropagação calcula?`,back:`O gradiente da perda em relação a cada peso, usando a regra da cadeia.`},{id:`l13-redes-neurais#2`,front:`O que faz a ReLU?`,back:`Devolve max(0, x).`}],"l13-ia-generativa":[{id:`l13-ia-generativa#1`,front:`O que é uma alucinação de um LLM?`,back:`Uma resposta fluente e confiante, porém falsa ou inventada.`},{id:`l13-ia-generativa#2`,front:`Qual a regra de ouro para aprender com IA?`,back:`Tentar primeiro e usar a IA para dicas, perguntas e revisão, verificando tudo.`}],"l14-logica-conjuntos":[{id:`l14-logica-conjuntos#1`,front:`Enuncie uma lei de De Morgan.`,back:`not (a and b) ≡ (not a) or (not b).`},{id:`l14-logica-conjuntos#2`,front:`Quando p → q é falsa?`,back:`Somente quando p é verdadeiro e q é falso.`},{id:`l14-logica-conjuntos#3`,front:`Quantos subconjuntos tem um conjunto de n elementos?`,back:`2ⁿ.`}],"l14-combinatoria-probabilidade":[{id:`l14-combinatoria-probabilidade#1`,front:`Fórmula de C(n, k)?`,back:`n! / (k!(n−k)!).`},{id:`l14-combinatoria-probabilidade#2`,front:`O que diz o teorema de Bayes?`,back:`P(A|B) = P(B|A)·P(A) / P(B).`},{id:`l14-combinatoria-probabilidade#3`,front:`Por que a mediana é mais robusta que a média?`,back:`Porque não é puxada por valores extremos.`}],"l14-discreta":[{id:`l14-discreta#1`,front:`Quais as duas partes de uma prova por indução?`,back:`O caso base e o passo indutivo (P(k) implica P(k+1)).`},{id:`l14-discreta#2`,front:`O que é um invariante de laço?`,back:`Uma propriedade verdadeira antes e depois de cada iteração, usada para provar que o laço produz o resultado certo.`},{id:`l14-discreta#3`,front:`Solução de T(n) = 2T(n/2) + n?`,back:`O(n log n).`},{id:`l14-discreta#4`,front:`Como testar se um grafo é bipartido?`,back:`Colorir com duas cores numa BFS; se uma aresta liga vértices de mesma cor, não é.`},{id:`l14-discreta#5`,front:`Quantas multiplicações a exponenciação rápida faz?`,back:`O(log e), uma ou duas por bit do expoente.`}],"l14-algebra-calculo":[{id:`l14-algebra-calculo#1`,front:`O que significa produto escalar zero?`,back:`Os vetores são perpendiculares (ortogonais).`},{id:`l14-algebra-calculo#2`,front:`Quando A·B está definido?`,back:`Quando o número de colunas de A é igual ao número de linhas de B.`},{id:`l14-algebra-calculo#3`,front:`Fórmula da atualização na descida do gradiente?`,back:`θ ← θ − α·∇f(θ).`},{id:`l14-algebra-calculo#4`,front:`O que a regra da cadeia tem a ver com redes neurais?`,back:`A retropropagação calcula os gradientes aplicando a regra da cadeia camada por camada.`}]};export{e as default};
